    g.set(gated, out.inputs['Geometry'])
    g.set(repeat_out.outputs['Valid'], out.inputs['Valid'])
    tree['revision'] = REVISION
    tree['construction'] = 'Native live ordered paths; bounded circular fillets; arc-length Grid quads; exact mouth profiles and tangents'
